def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('budget', 0) >= bid:
                    dangerous_prev.append(float(bid))

    if not alive:
        base = DAILY_SALARY * 0.35
        if no_water >= 2 or hp <= 3:
            base = DAILY_SALARY * 0.75
        return float(min(budget, max(0.0, base)))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0
    high_danger = max(dangerous_prev) if dangerous_prev else highest_prev

    my_need_urgent = (no_water >= 2 or hp <= 3)
    need_water = (no_water >= 1 or hp <= 6)

    guaranteed_winners = int(supply // WATER_REQ)
    if guaranteed_winners < 1:
        guaranteed_winners = 1

    alive_count = len(alive)
    scarcity = alive_count - guaranteed_winners

    if guaranteed_winners == 1:
        if my_need_urgent:
            bid = max(DAILY_SALARY * 1.6, high_danger + 8.0, avg_prev + 18.0)
        elif need_water:
            bid = max(DAILY_SALARY * 1.15, high_danger + 3.0)
        else:
            bid = DAILY_SALARY * 0.28
    else:
        if my_need_urgent:
            bid = max(DAILY_SALARY * 0.95, avg_prev + 2.0)
        elif need_water:
            if scarcity >= 2:
                bid = max(DAILY_SALARY * 0.72, avg_prev * 0.78, 52.0)
            else:
                bid = max(DAILY_SALARY * 0.55, avg_prev * 0.62, 38.0)
        else:
            if scarcity >= 2:
                bid = max(24.0, min(DAILY_SALARY * 0.48, avg_prev * 0.5 if avg_prev > 0 else 30.0))
            else:
                bid = 18.0

    if budget < DAILY_SALARY and not my_need_urgent:
        bid = min(bid, budget * 0.55)

    if day >= 8 and (hp <= 5 or no_water >= 1):
        bid = max(bid, min(budget, high_danger + 4.0 if high_danger > 0 else DAILY_SALARY * 0.9))

    bid = min(budget, max(0.0, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids for immediate reaction
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    pressure = 0.0
    if prev_bids:
        pressure = max(prev_bids)

    # Supply tightness: if supply is near minimum, water is scarce -> bid more
    # Use a smooth factor rather than exact thresholds
    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY + 1e-9)
    scarcity = max(0.0, min(1.0, scarcity))

    # If we've already gone without water, increase urgency
    urgency = 0.0
    if my_no_water_days >= 2:
        urgency = 1.0
    elif my_no_water_days == 1:
        urgency = 0.6
    else:
        urgency = 0.25

    # HP-based risk: lower HP -> bid more
    hp_factor = 0.0
    if my_hp <= 2:
        hp_factor = 1.0
    elif my_hp <= 4:
        hp_factor = 0.75
    elif my_hp <= 7:
        hp_factor = 0.45
    else:
        hp_factor = 0.25

    # Target bid baseline: anchor to yesterday pressure but avoid overpaying
    # If pressure was high, match a fraction of it; otherwise bid around a mid level.
    if pressure > 0:
        # Match enough to beat typical surviving bids; add scarcity/urgency/Hp pressure
        base = pressure * (0.85 - 0.25 * hp_factor) + (DAILY_SALARY * 0.15)
    else:
        base = DAILY_SALARY * 0.55

    # Adjust upward for scarcity and urgency
    multiplier = 1.0 + 0.35 * scarcity + 0.35 * urgency + 0.25 * hp_factor
    bid = base * multiplier

    # Cap bid to budget and to a reasonable fraction of budget to preserve optionality
    # (Budget can be small; never exceed it.)
    max_allow = my_budget
    # Also keep bids from going extreme when budget is large
    soft_cap = DAILY_SALARY * (0.95 + 0.15 * scarcity)
    bid = min(bid, soft_cap, max_allow)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # If our budget is very low, bid it all to avoid dying
    if my_budget <= DAILY_SALARY * 0.2:
        return min(my_budget, DAILY_SALARY * 0.95)

    # If supply is very tight, ensure a minimum competitive bid
    if supply <= float(MIN_SUPPLY):
        min_competitive = DAILY_SALARY * (0.6 + 0.25 * urgency)
        bid = max(bid, min_competitive)
        bid = min(bid, my_budget)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    avg_opp_bid = 0
    count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            avg_opp_bid += prev['bid']
            count += 1

    avg_bid = (avg_opp_bid / count) if count > 0 else 100.0

    if supply < 18.0:
        bid = avg_bid * 1.1
    elif supply < 22.0:
        bid = avg_bid * 0.9
    else:
        bid = avg_bid * 0.7

    if my_status['hp'] < 4:
        bid = max(bid, 130.0)

    return min(my_status['budget'], float(bid))
